-- Trace and hourly quota of the downstream service email notifications.
-- Mirrors the Postgres `notification_dispatch` table (migration
-- 20261120_01) with this adapter's SQLite type mapping (see
-- migrations/2026-07-06-000000_init/up.sql header):
--   UUID        -> TEXT (hyphenated string, generated by the app)
--   TIMESTAMPTZ -> TEXT (UTC, written by the app)
--
-- `created_at` has no DB-side default: the app writes it in a fixed-width
-- form (`YYYY-MM-DDTHH:MM:SS.ffffffZ`) so the quota window and the retention
-- purge can compare it as text.
--
-- No FOREIGN KEY to `token` (deleting a connection string must not erase the
-- trace) nor to `message_queue` (delivered messages are deleted). Template
-- variables are not stored, since they may hold personal data.

CREATE TABLE notification_dispatch (
    id TEXT NOT NULL PRIMARY KEY,
    sender_tag TEXT NOT NULL,
    channel TEXT NOT NULL DEFAULT 'email',
    connection_string_id INTEGER NOT NULL,
    account_id TEXT NOT NULL,
    tenant_id TEXT,
    recipient TEXT NOT NULL,
    template TEXT NOT NULL,
    locale TEXT NOT NULL,
    created_at TEXT NOT NULL
);

CREATE INDEX notification_dispatch_tag_created_idx
    ON notification_dispatch (sender_tag, created_at);
